app = FastAPI()

class CreateItemRequest(BaseModel):
    name: str = Field(min_length=1, max_length=80)
    quantity: int = Field(ge=1, le=1000)

@app.post("/items")
def create_item(request: CreateItemRequest):
    return {"name": request.name, "quantity": request.quantity}

Pydantic проверяет JSON перед входом в обработчик. Возвращай конкретные типы данных и не принимай произвольный SQL от клиента.

async function sendJson(url, payload) {
    const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
    });
    if (!response.ok) {
        throw new Error("HTTP " + response.status);
    }
    return await response.json();
}

Вызывай функцию через await внутри async обработчика и показывай пользователю понятную ошибку при сетевом сбое.

