func create_enemy(scene_path: String, parent: Node) -> Node:
    if not ResourceLoader.exists(scene_path):
        push_error("Scene does not exist: " + scene_path)
        return null
    var packed := load(scene_path) as PackedScene
    if packed == null:
        push_error("Resource is not a PackedScene")
        return null
    var instance := packed.instantiate()
    parent.add_child(instance)
    return instance

Для часто создаваемых объектов лучше заранее назначать PackedScene через export и не загружать ресурс каждый кадр.
